-- TMS PostgreSQL bootstrap schema (PostgreSQL 13+).
-- Run this once on an empty database, then start the external-postgres compose file.
-- Existing PostgreSQL installations may use their own migration tooling; all ids use identity columns.

CREATE TABLE IF NOT EXISTS "forward" (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id integer NOT NULL, user_name varchar(100) NOT NULL, name varchar(100) NOT NULL, tunnel_id integer NOT NULL, in_port integer NOT NULL, out_port integer, remote_addr text NOT NULL, strategy varchar(100) NOT NULL DEFAULT 'fifo', interface_name varchar(200), in_flow bigint NOT NULL DEFAULT 0, out_flow bigint NOT NULL DEFAULT 0, created_time bigint NOT NULL, updated_time bigint NOT NULL, status integer NOT NULL, inx integer NOT NULL DEFAULT 0, speed_id integer, exp_time bigint);
CREATE TABLE IF NOT EXISTS node (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL, secret varchar(100) NOT NULL, ip text, server_ip varchar(100) NOT NULL, domain varchar(255), cert_mode integer NOT NULL DEFAULT 0, cert_path varchar(500), key_path varchar(500), port_sta integer NOT NULL, port_end integer NOT NULL, version varchar(100), http integer NOT NULL DEFAULT 0, tls integer NOT NULL DEFAULT 0, socks integer NOT NULL DEFAULT 0, created_time bigint NOT NULL, updated_time bigint, status integer NOT NULL);
CREATE TABLE IF NOT EXISTS speed_limit (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL, speed integer NOT NULL, mode smallint NOT NULL DEFAULT 0, total integer NOT NULL DEFAULT 0, tunnel_id bigint, tunnel_name varchar(100) NOT NULL, created_time bigint NOT NULL, updated_time bigint, status integer NOT NULL);
CREATE TABLE IF NOT EXISTS statistics_flow (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id integer NOT NULL, flow bigint NOT NULL, total_flow bigint NOT NULL, time varchar(100) NOT NULL, created_time bigint NOT NULL);
CREATE TABLE IF NOT EXISTS tunnel (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL, traffic_ratio numeric(10,1) NOT NULL DEFAULT 1.0, in_node_id integer NOT NULL, in_ip varchar(100) NOT NULL, out_node_id integer NOT NULL, out_ip varchar(100) NOT NULL, type integer NOT NULL, protocol varchar(10) NOT NULL DEFAULT 'tls', flow integer NOT NULL, tcp_listen_addr varchar(100) NOT NULL DEFAULT '[::]', udp_listen_addr varchar(100) NOT NULL DEFAULT '[::]', interface_name varchar(200), created_time bigint NOT NULL, updated_time bigint NOT NULL, status integer NOT NULL);
CREATE TABLE IF NOT EXISTS "user" (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "user" varchar(100) NOT NULL, pwd varchar(100) NOT NULL, role_id integer NOT NULL, exp_time bigint NOT NULL DEFAULT 0, flow bigint NOT NULL DEFAULT 0, in_flow bigint NOT NULL DEFAULT 0, out_flow bigint NOT NULL DEFAULT 0, flow_reset_time bigint NOT NULL DEFAULT 1, num integer NOT NULL DEFAULT 0, all_sub_token varchar(64), email varchar(190), created_time bigint NOT NULL, updated_time bigint, status integer NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uk_user_email ON "user" (email) WHERE email IS NOT NULL;
CREATE TABLE IF NOT EXISTS user_tunnel (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id integer NOT NULL, tunnel_id integer NOT NULL, speed_id integer, num integer NOT NULL, flow bigint NOT NULL, in_flow bigint NOT NULL DEFAULT 0, out_flow bigint NOT NULL DEFAULT 0, flow_reset_time bigint NOT NULL, exp_time bigint NOT NULL, status integer NOT NULL);
CREATE TABLE IF NOT EXISTS vite_config (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(200) NOT NULL UNIQUE, value varchar(200) NOT NULL, time bigint NOT NULL);
CREATE TABLE IF NOT EXISTS inbound (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, node_id integer NOT NULL, tag varchar(100) NOT NULL, protocol varchar(50) NOT NULL, listen_port integer NOT NULL, security varchar(20) NOT NULL DEFAULT 'reality', sni varchar(255), dest varchar(255), public_key varchar(255), private_key varchar(255), short_id varchar(100), config_json text, remark varchar(255), status integer NOT NULL DEFAULT 1, created_time bigint NOT NULL, updated_time bigint, landing_id integer);
CREATE TABLE IF NOT EXISTS inbound_user (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, inbound_id integer NOT NULL, user_id integer NOT NULL, uuid varchar(100), password varchar(255), gost_forward_id integer, sub_token varchar(100), status integer NOT NULL DEFAULT 1, created_time bigint NOT NULL);
CREATE TABLE IF NOT EXISTS landing (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL, type varchar(30) NOT NULL, link text, outbound_json text, remark varchar(255), status integer NOT NULL DEFAULT 1, created_time bigint NOT NULL, updated_time bigint);
CREATE TABLE IF NOT EXISTS inbound_line (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id integer NOT NULL, node_id integer NOT NULL, landing_id integer, sub_token varchar(100), flow bigint, exp_time bigint, status integer NOT NULL DEFAULT 1, created_time bigint NOT NULL, updated_time bigint);

CREATE TABLE IF NOT EXISTS subscription_plan (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL, description varchar(500), price numeric(12,2) NOT NULL DEFAULT 0, currency varchar(10) NOT NULL DEFAULT 'CNY', validity_value integer NOT NULL, validity_unit varchar(10) NOT NULL DEFAULT 'month', traffic_bytes bigint NOT NULL DEFAULT 0, reset_day smallint NOT NULL DEFAULT 1, max_forwards integer NOT NULL DEFAULT 0, for_sale smallint NOT NULL DEFAULT 1, redeemable smallint NOT NULL DEFAULT 1, sort_order integer NOT NULL DEFAULT 0, status smallint NOT NULL DEFAULT 1, created_time bigint NOT NULL, updated_time bigint NOT NULL);
CREATE TABLE IF NOT EXISTS user_subscription (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL UNIQUE, plan_id bigint NOT NULL, starts_at bigint NOT NULL, expires_at bigint NOT NULL, traffic_limit_bytes bigint NOT NULL DEFAULT 0, traffic_used_bytes bigint NOT NULL DEFAULT 0, next_reset_at bigint, max_forwards integer NOT NULL DEFAULT 0, used_forwards integer NOT NULL DEFAULT 0, status smallint NOT NULL DEFAULT 1, created_time bigint NOT NULL, updated_time bigint NOT NULL);
CREATE TABLE IF NOT EXISTS redeem_code (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, plan_id bigint NOT NULL, code_hash char(64) NOT NULL UNIQUE, code_preview varchar(20) NOT NULL, batch_id varchar(64), status smallint NOT NULL DEFAULT 1, used_by bigint, used_time bigint, expires_at bigint, remark varchar(255), created_time bigint NOT NULL);
CREATE TABLE IF NOT EXISTS quota_usage_log (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL, subscription_id bigint, event_type varchar(32) NOT NULL, amount bigint NOT NULL DEFAULT 0, metadata jsonb, created_time bigint NOT NULL);
CREATE TABLE IF NOT EXISTS payment_order (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_no varchar(64) NOT NULL UNIQUE, user_id bigint NOT NULL, plan_id bigint NOT NULL, provider varchar(20) NOT NULL, amount numeric(12,2) NOT NULL, currency varchar(10) NOT NULL DEFAULT 'CNY', status varchar(20) NOT NULL DEFAULT 'pending', provider_trade_no varchar(128), callback_payload text, paid_at bigint, created_time bigint NOT NULL, updated_time bigint NOT NULL);
CREATE TABLE IF NOT EXISTS custom_node (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255) NOT NULL, protocol varchar(32) NOT NULL, raw_link text NOT NULL, parsed_json text NOT NULL, status smallint NOT NULL DEFAULT 1, created_time bigint NOT NULL, updated_time bigint NOT NULL);
CREATE TABLE IF NOT EXISTS user_custom_node (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL, custom_node_id bigint NOT NULL, status smallint NOT NULL DEFAULT 1, created_time bigint NOT NULL, UNIQUE(user_id, custom_node_id));
CREATE TABLE IF NOT EXISTS verification_code (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email varchar(190) NOT NULL, purpose varchar(32) NOT NULL, code_hash varchar(100) NOT NULL, expires_at bigint NOT NULL, sent_at bigint NOT NULL, attempts integer NOT NULL DEFAULT 0, consumed_at bigint, created_at bigint NOT NULL DEFAULT 0, UNIQUE(email, purpose));

INSERT INTO "user" (id, "user", pwd, role_id, exp_time, flow, in_flow, out_flow, flow_reset_time, num, created_time, updated_time, status)
SELECT 1, 'admin_user', '3c85cdebade1c51cf64ca9f3c09d182d', 0, 2727251700000, 99999, 0, 0, 1, 99999, (extract(epoch from now()) * 1000)::bigint, (extract(epoch from now()) * 1000)::bigint, 1
WHERE NOT EXISTS (SELECT 1 FROM "user");
INSERT INTO vite_config (name, value, time) SELECT 'app_name', 'TMS', (extract(epoch from now()) * 1000)::bigint WHERE NOT EXISTS (SELECT 1 FROM vite_config WHERE name = 'app_name');
